    DATA = ""

    def unpack(data: str) -> dict:
        blob = zlib.decompress(base64.b64decode(data))
        (n,) = struct.unpack("<I", blob[:4])
        body = memoryview(blob)[4 + n :]

        def walk(x):
            if isinstance(x, dict):
                if "__a" in x:
                    start, size = x["__a"]
                    return np.frombuffer(body[start : start + size], dtype=x["dtype"]).reshape(x["shape"])
                return {k: walk(v) for k, v in x.items()}
            if isinstance(x, list):
                return [walk(v) for v in x]
            return x

        return walk(json.loads(blob[4 : 4 + n]))

    D = unpack(DATA)
    INK = "currentColor"
    RULE = "var(--lightgray, #E3DFD9)"
    MUTED = "var(--gray, #92908E)"
    MONO = "var(--codeFont, 'IBM Plex Mono', monospace)"
    ORANGE, TEAL, SLATE = "#E89A39", "#587571", "#748C9C"

    def b64(a) -> str:
        return base64.b64encode(np.ascontiguousarray(a).tobytes()).decode()

    MESH = {k: (b64(v) if isinstance(v, np.ndarray) else v) for k, v in D["mesh"].items()}

