@app.class_definition(hide_code=True)
class BrainView(anywidget.AnyWidget):
    """data: {mesh, maps: {key: {q, lo, hi, cmap, palette?, cats?}}, groups: [[[value, label], ...]], initial: [values]}"""

    _esm = BRAIN_JS + r"""
    function render({ model, el }) {
      const D = model.get("data"), mesh = makeMesh(D.mesh);
      const maps = Object.fromEntries(Object.entries(D.maps).map(([k, m]) => [k, { ...m, q: u8(m.q) }]));
      const root = el_("div", "brv", el), state = [...D.initial];
      D.groups.forEach((g, gi) => {
        const row = el_("div", "pills", root);
        for (const [v, label] of g) {
          const b = el_("button", "", row); b.textContent = label;
          b.addEventListener("click", () => { state[gi] = v; draw(); });
        }
      });
      const panel = brainPanel(root, mesh);
      const legend = el_("div", "brv-legend", root);
      function draw() {
        root.querySelectorAll(".pills").forEach((row, gi) => row.querySelectorAll("button").forEach((b, i) => b.setAttribute("aria-pressed", D.groups[gi][i][0] === state[gi])));
        const m = maps[state.join("/")];
        const spec = { cmap: m.cmap, lo: m.lo, hi: m.hi, palette: m.palette,
          describe: m.cats ? (q, r) => { const c = new Array(m.cats.length).fill(0); for (const v of mesh.members[r]) if (q[v] < 255) c[Math.round(q[v] / 254 * (m.cats.length - 1))]++; return m.cats[c.indexOf(Math.max(...c))]; } : null };
        panel.draw(m.q, spec);
        legend.replaceChildren();
        if (m.cats) { for (const [name, color] of m.legend) { const s = el_("span", "", legend); el_("i", "", s).style.background = color; s.append(name); } }
        else { const s = el_("span", "", legend); s.append(m.lo.toFixed(1)); el_("b", m.cmap, s); s.append(m.hi.toFixed(1)); }
      }
      draw();
      return watchTheme(draw);
    }
    export default { render };
    """
    _css = BRAIN_CSS + r"""
    .brv-legend { display: flex; gap: 1rem; font-size: 11px; opacity: 0.75; font-family: var(--codeFont, monospace); }
    .brv-legend span { display: inline-flex; align-items: center; gap: 0.35rem; }
    .brv-legend i { width: 10px; height: 10px; border-radius: 2px; display: inline-block; }
    .brv-legend b { width: 90px; height: 8px; border-radius: 2px; display: inline-block; }
    .brv-legend b.seq { background: linear-gradient(90deg, color-mix(in srgb, currentColor 12%, transparent), #E89A39, #AA521C); }
    .brv-legend b.div { background: linear-gradient(90deg, #244240, #587571, color-mix(in srgb, currentColor 12%, transparent), #E89A39, #AA521C); }
    """
    data = traitlets.Dict().tag(sync=True)


