@app.function(hide_code=True)
def concepts_svg(c):
    """Scatter (measured vs predicted cortex) and per-concept ladder curves in one SVG, linked by CSS :has()."""
    targets, kinds = c["targets"], c["kinds"]
    binary = [i for i, k in enumerate(kinds) if k in ("super", "object")]
    pred, meas = np.mean(c["predicted"], 0), np.mean(c["measured"], 0)
    lad = np.array(c["ladder"])
    W, H, L, T = 250, 250, 52, 20
    lo, hi = 0.65, 1.0
    sx = lambda v: L + (v - lo) / (hi - lo) * W
    sy = lambda v: T + H - (v - lo) / (hi - lo) * H
    parts = [f'<line x1="{sx(lo)}" y1="{sy(lo)}" x2="{sx(hi)}" y2="{sy(hi)}" stroke="{RULE}"/>']
    for t in (0.7, 0.85, 1.0):
        parts.append(text(sx(t), T + H + 14, f"{t:.2f}", "middle", MUTED, 10, True) + text(L - 6, sy(t), f"{t:.2f}", "end", MUTED, 10, True))
    parts.append(text(L + W / 2, T + H + 30, "measured cortex (AUC)", "middle", MUTED, 11))
    parts.append(text(L - 42, T + H / 2, "TRIBE's cortex", "middle", MUTED, 11, extra=f'transform="rotate(-90 {L - 42} {T + H / 2})"'))
    fit = np.polyfit(meas[binary], pred[binary], 1)
    resid = pred[binary] - np.polyval(fit, meas[binary])
    keep = {binary[i] for i in np.argsort(resid)[:2]} | {binary[i] for i in np.argsort(resid)[-2:]}
    def crowded(i):  # another point under a right-hand label
        x0, y0, x1 = sx(meas[i]) + 2, sy(pred[i]), sx(meas[i]) + 9 + 6.2 * len(targets[i])
        return any(j != i and x0 < sx(meas[j]) < x1 and abs(sy(pred[j]) - y0) < 8 for j in binary)
    label_side = lambda i: "end" if crowded(i) else "start"
    label_at = lambda i: (sx(meas[i]) + (-7 if crowded(i) else 7), sy(pred[i]))
    L2, W2 = L + W + 70, 300
    x2 = lambda i: L2 + i / (lad.shape[0] - 1) * W2
    y2 = lambda v: T + H - (np.clip(v, lo, hi) - lo) / (hi - lo) * H
    parts.append(text(L2, T + H + 14, "V-JEPA2 1", "start", MUTED, 10) + text(L2 + W2, T + H + 14, "state", "end", MUTED, 10))
    for t in (0.7, 0.85, 1.0):
        parts.append(f'<line x1="{L2}" x2="{L2 + W2}" y1="{y2(t)}" y2="{y2(t)}" stroke="{RULE}"/>')
    for i in binary:
        color = ORANGE if c["kinds"][i] == "super" else SLATE
        curve = path([(x2(k), y2(v)) for k, v in enumerate(lad[:, i])], color, 1.4, "", 'opacity="0.55"')
        parts.append(f'<g class="c">{curve}<circle cx="{sx(meas[i])}" cy="{sy(pred[i])}" r="4" fill="{color}" opacity="0.85">'
                     f'<title>{targets[i]}: measured {meas[i]:.2f}, TRIBE {pred[i]:.2f}</title></circle>'
                     + text(*label_at(i), targets[i], label_side(i), INK, 11, extra=f'class="lab{" keep" if i in keep else ""}"')
                     + text(L2 + W2 + 6, y2(lad[-1, i]), targets[i], "start", color, 11, extra='class="lab"') + "</g>")
    return svg(L2 + W2 + 110, T + H + 40, "".join(parts), "concepts")


