@app.function(hide_code=True)
def pixels_svg(c):
    """Correlation of probe predictions with each continuous target: measured cortex (ink) against TRIBE's (orange)."""
    rows = [i for i, k in enumerate(c["kinds"]) if k in ("pixel", "count")]
    pred, meas = np.mean(c["predicted"], 0), np.mean(c["measured"], 0)
    left, track, pitch, top = 120, 330, 24, 22
    x = lambda v: left + max(0.0, v) * track
    parts = [text(x(meas[rows[0]]) - 9, 8, "cortex", "end", MUTED, 11), text(x(pred[rows[0]]) + 9, 8, "TRIBE", "start", ORANGE, 11)]
    axis = top + len(rows) * pitch
    for t in (0, 0.5, 1.0):
        parts.append(f'<line x1="{x(t)}" x2="{x(t)}" y1="{top - 6}" y2="{axis}" stroke="{RULE}"/>' + text(x(t), axis + 12, f"r = {t:.1f}" if t == 0 else f"{t:.1f}", "middle", MUTED, 10, True))
    for j, i in enumerate(rows):
        y = top + j * pitch + pitch / 2
        parts.append(f'<g class="m">{text(left - 14, y, c["targets"][i], "end")}'
                     f'<line x1="{x(meas[i])}" x2="{x(pred[i])}" y1="{y}" y2="{y}" stroke="{ORANGE}" stroke-width="2" opacity="0.5"/>'
                     f'<circle cx="{x(meas[i])}" cy="{y}" r="5" fill="none" stroke="{INK}" stroke-width="2"><title>measured cortex {meas[i]:.2f}</title></circle>'
                     f'<circle cx="{x(pred[i])}" cy="{y}" r="5" fill="{ORANGE}"><title>TRIBE cortex {pred[i]:.2f}</title></circle></g>')
    return svg(left + track + 40, axis + 22, "".join(parts))


